import { createFileRoute } from "@tanstack/react-router";
import {
  Activity,
  AlertTriangle,
  ArrowRight,
  BadgeCheck,
  BarChart3,
  Bell,
  Check,
  CheckCircle2,
  ChevronRight,
  CircleHelp,
  CloudOff,
  Download,
  Eye,
  FileText,
  Gauge,
  HeartPulse,
  Info,
  Languages,
  LayoutDashboard,
  Menu,
  Microscope,
  MoreHorizontal,
  Network,
  Play,
  Plus,
  RefreshCw,
  ScanLine,
  Search,
  Settings,
  ShieldCheck,
  Stethoscope,
  Upload,
  UserRound,
  Wifi,
  X,
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";

import fundusImage from "@/assets/fundus-moderate.jpg";

export const Route = createFileRoute("/")({
  head: () => ({
    meta: [
      { title: "DrishtiAI — Explainable DR Screening" },
      { name: "description", content: "Explainable diabetic retinopathy screening for rural India." },
      { property: "og:title", content: "DrishtiAI — Explainable DR Screening" },
      { property: "og:description", content: "Clinical AI you can inspect, not just trust." },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary_large_image" },
    ],
  }),
  component: DrishtiAI,
});

type View = "overview" | "screening" | "records" | "review" | "offline" | "analytics" | "model" | "settings";
type Scenario = "moderate" | "healthy" | "poor" | "clever";
type ScreeningStep = "patient" | "capture" | "quality" | "analysis" | "explainability" | "referral";
type ViewerMode = "original" | "gradcam" | "lesions" | "combined";

type RecordItem = {
  id: string;
  patient: string;
  village: string;
  date: string;
  grade: string;
  confidence: number;
  reasoning: number;
  referral: string;
  sync: string;
  reviewer: string;
};

const navItems: { id: View; label: string; icon: typeof LayoutDashboard }[] = [
  { id: "overview", label: "Overview", icon: LayoutDashboard },
  { id: "screening", label: "New Screening", icon: ScanLine },
  { id: "records", label: "Screening Records", icon: FileText },
  { id: "review", label: "Review Queue", icon: Stethoscope },
  { id: "offline", label: "Offline Sync", icon: CloudOff },
  { id: "analytics", label: "Analytics", icon: BarChart3 },
  { id: "model", label: "Model Insights", icon: Network },
  { id: "settings", label: "Settings", icon: Settings },
];

const initialRecords: RecordItem[] = [
  { id: "DR-2026-00142", patient: "Sunita Devi", village: "Shivpura", date: "Today, 10:42", grade: "Moderate", confidence: 93, reasoning: 87, referral: "Refer", sync: "Synced", reviewer: "—" },
  { id: "DR-2026-00141", patient: "Ramesh Kumar", village: "Rampur", date: "Today, 09:18", grade: "No DR", confidence: 97, reasoning: 92, referral: "Routine", sync: "Synced", reviewer: "—" },
  { id: "DR-2026-00140", patient: "Meena Bai", village: "Devgaon", date: "Yesterday, 16:28", grade: "Severe", confidence: 96, reasoning: 28, referral: "Review", sync: "Synced", reviewer: "Pending" },
  { id: "DR-2026-00139", patient: "Arjun Singh", village: "Nandgaon", date: "Yesterday, 14:05", grade: "Mild", confidence: 89, reasoning: 82, referral: "Refer", sync: "Waiting", reviewer: "—" },
  { id: "DR-2026-00138", patient: "Kamla Devi", village: "Bhadra", date: "05 Sep, 11:40", grade: "No DR", confidence: 98, reasoning: 94, referral: "Routine", sync: "Synced", reviewer: "—" },
];

const scenarios: Record<Scenario, { label: string; grade: string; confidence: number; reasoning: number; referral: string; quality: "good" | "poor" }> = {
  moderate: { label: "Moderate DR", grade: "Moderate", confidence: 93, reasoning: 87, referral: "Refer", quality: "good" },
  healthy: { label: "Healthy Retina", grade: "No DR", confidence: 97, reasoning: 92, referral: "Routine", quality: "good" },
  poor: { label: "Poor Image", grade: "Withheld", confidence: 0, reasoning: 0, referral: "Retake", quality: "poor" },
  clever: { label: "Clever Hans / Low Concordance", grade: "Severe", confidence: 96, reasoning: 28, referral: "Review", quality: "good" },
};

function DrishtiAI() {
  const [entered, setEntered] = useState(false);
  const [view, setView] = useState<View>("overview");
  const [mobileNav, setMobileNav] = useState(false);
  const [online, setOnline] = useState(true);
  const [scenario, setScenario] = useState<Scenario>("moderate");
  const [screeningStep, setScreeningStep] = useState<ScreeningStep>("patient");
  const [viewer, setViewer] = useState<ViewerMode>("gradcam");
  const [lowConcordance, setLowConcordance] = useState(false);
  const [poorCapture, setPoorCapture] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [syncProgress, setSyncProgress] = useState(0);
  const [reportOpen, setReportOpen] = useState(false);
  const [reportLanguage, setReportLanguage] = useState("English");
  const [toast, setToast] = useState<string | null>(null);
  const [records, setRecords] = useState<RecordItem[]>(initialRecords);
  const [offlineQueue, setOfflineQueue] = useState(8);
  const [search, setSearch] = useState("");
  const [reviewed, setReviewed] = useState(false);

  const result = scenarios[scenario];
  const reasoning = lowConcordance || scenario === "clever" ? 28 : result.reasoning;
  const referral = lowConcordance || scenario === "clever" ? "Review" : result.referral;

  useEffect(() => {
    if (!toast) return;
    const timeout = window.setTimeout(() => setToast(null), 3200);
    return () => window.clearTimeout(timeout);
  }, [toast]);

  useEffect(() => {
    if (!syncing) return;
    if (syncProgress >= 8) {
      setSyncing(false);
      setOfflineQueue(0);
      setToast("All records synced successfully.");
      return;
    }
    const timeout = window.setTimeout(() => setSyncProgress((value) => value + 1), 420);
    return () => window.clearTimeout(timeout);
  }, [syncing, syncProgress]);

  const showApp = (nextView: View) => {
    setEntered(true);
    setView(nextView);
    setMobileNav(false);
  };

  const chooseScenario = (next: Scenario) => {
    setScenario(next);
    setPoorCapture(next === "poor");
    setLowConcordance(next === "clever");
    setScreeningStep(next === "poor" ? "quality" : "explainability");
    setToast(`${scenarios[next].label} scenario loaded.`);
  };

  const runAnalysis = () => {
    setAnalyzing(true);
    window.setTimeout(() => {
      setAnalyzing(false);
      setScreeningStep("explainability");
      setToast("Analysis complete. Evidence is ready to inspect.");
    }, 1500);
  };

  const completeOfflineScreening = () => {
    setOfflineQueue((value) => value + 1);
    setRecords((items) => [{ ...items[0], id: "DR-2026-00146", date: "Just now", sync: "Waiting", reviewer: "—" }, ...items]);
    setToast("Screening saved locally. It will sync when connectivity returns.");
  };

  if (!entered) {
    return <Landing onEnter={() => showApp("screening")} onDashboard={() => showApp("overview")} />;
  }

  return (
    <div className="clinical-wash min-h-screen text-navy">
      <div className="mx-auto flex min-h-screen max-w-[1520px] gap-5 px-3 py-3 sm:px-5 sm:py-5">
        <Sidebar view={view} onNavigate={showApp} mobileNav={mobileNav} onClose={() => setMobileNav(false)} />
        <main className="min-w-0 flex-1">
          <Topbar online={online} onToggle={() => { setOnline((value) => !value); setToast(online ? "Offline Mode enabled. Screenings will be stored locally." : "Connection restored."); }} onMenu={() => setMobileNav(true)} />
          <div className="mt-5 animate-slide-up">
            {view === "overview" && <Overview onNavigate={showApp} offlineQueue={offlineQueue} />}
            {view === "screening" && <ScreeningWorkspace scenario={scenario} result={result} step={screeningStep} setStep={setScreeningStep} viewer={viewer} setViewer={setViewer} lowConcordance={lowConcordance} setLowConcordance={setLowConcordance} poorCapture={poorCapture} setPoorCapture={setPoorCapture} analyzing={analyzing} runAnalysis={runAnalysis} online={online} onCompleteOffline={completeOfflineScreening} onReport={() => setReportOpen(true)} chooseScenario={chooseScenario} />}
            {view === "records" && <Records records={records} search={search} setSearch={setSearch} onOpen={() => { setView("screening"); setScreeningStep("explainability"); }} />}
            {view === "review" && <ReviewQueue reviewed={reviewed} setReviewed={setReviewed} onOpen={() => setView("screening")} />}
            {view === "offline" && <OfflineSync online={online} queue={offlineQueue} syncing={syncing} progress={syncProgress} onSync={() => { setSyncProgress(0); setSyncing(true); }} />}
            {view === "analytics" && <Analytics />}
            {view === "model" && <ModelInsights />}
            {view === "settings" && <SettingsPanel />}
          </div>
        </main>
      </div>
      {reportOpen && <ReportModal language={reportLanguage} setLanguage={setReportLanguage} onClose={() => setReportOpen(false)} onDownload={() => setToast("Demo report exported.")} />}
      {toast && <div role="status" className="fixed bottom-5 left-1/2 z-50 flex -translate-x-1/2 items-center gap-3 rounded-xl bg-navy px-4 py-3 text-sm text-primary-foreground shadow-xl"><CheckCircle2 className="size-4 text-teal" />{toast}</div>}
    </div>
  );
}

function Landing({ onEnter, onDashboard }: { onEnter: () => void; onDashboard: () => void }) {
  return (
    <div className="clinical-wash min-h-screen text-navy">
      <div className="mx-auto max-w-[1320px] px-5 py-5 sm:px-8 sm:py-8">
        <header className="frosted spec-border flex items-center justify-between rounded-[18px] px-4 py-3.5">
          <Brand />
          <div className="hidden items-center gap-2 text-xs text-mute sm:flex"><span className="size-2 rounded-full bg-emerald" /> Demo environment · PHC Rampur</div>
          <button onClick={onDashboard} className="rounded-lg px-3 py-2 text-sm font-medium text-ink transition hover:bg-primary/5">View Dashboard</button>
        </header>
        <section className="grid items-center gap-10 pb-14 pt-12 lg:grid-cols-[1fr_0.9fr] lg:pt-20">
          <div>
            <div className="mb-5 inline-flex items-center gap-2 rounded-full frosted spec-border px-3 py-1.5 text-xs font-medium text-ink"><span className="size-1.5 rounded-full bg-emerald" /> Capture · Understand · Refer — even offline</div>
            <h1 className="max-w-[12ch] font-display text-5xl font-semibold leading-[1.02] tracking-tight sm:text-7xl">Clinical AI you can <span className="text-emerald">inspect</span>, not just trust.</h1>
            <p className="mt-6 max-w-xl text-base leading-7 text-ink sm:text-lg">DrishtiAI helps frontline health workers screen for diabetic retinopathy with explainable AI, on-device quality checks, and confidence-aware referrals.</p>
            <div className="mt-8 flex flex-wrap gap-3"><button onClick={onEnter} className="inline-flex items-center gap-2 rounded-xl bg-navy px-5 py-3.5 text-sm font-semibold text-primary-foreground shadow-lg transition hover:bg-navy/90">Start Screening <ArrowRight className="size-4" /></button><button onClick={onDashboard} className="rounded-xl frosted spec-border px-5 py-3.5 text-sm font-semibold text-navy transition hover:bg-primary/5">View Clinical Dashboard</button></div>
            <div className="mt-10 flex flex-wrap gap-8 text-sm"><div><strong className="font-display text-2xl">97%</strong><p className="mt-1 text-xs text-mute">quality gate accuracy</p></div><div><strong className="font-display text-2xl">0.74</strong><p className="mt-1 text-xs text-mute">attention–lesion IoU</p></div><div><strong className="font-display text-2xl">5</strong><p className="mt-1 text-xs text-mute">ICDR grades</p></div></div>
          </div>
          <div className="frosted spec-border rounded-[24px] p-5 shadow-2xl shadow-navy/10"><RetinaViewer mode="gradcam" large /><div className="mt-4 grid grid-cols-3 gap-2"><Metric label="ICDR Grade" value="Moderate" tone="warning" /><Metric label="AI Confidence" value="93.2%" /><Metric label="Concordance" value="87%" tone="good" /></div><div className="mt-3 flex items-center justify-between rounded-xl bg-emerald/10 px-4 py-3 text-sm"><span className="font-semibold">Refer to Ophthalmologist</span><span className="rounded-full bg-emerald/15 px-3 py-1 text-xs font-medium text-emerald">Within 3 months</span></div></div>
        </section>
        <section className="border-t border-primary/10 py-10"><div className="mb-5 flex items-end justify-between"><div><p className="text-xs font-semibold uppercase tracking-[0.18em] text-emerald">The screening journey</p><h2 className="mt-1 font-display text-2xl font-semibold">Four safeguards, one clinical loop</h2></div><span className="hidden text-xs text-mute sm:block">Built for SIH26038 · Problem Statement by MathWorks</span></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Capability icon={<ShieldCheck />} title="On-device Quality Gate" copy="Blur, exposure, glare and centering are scored before inference." /><Capability icon={<Eye />} title="Explainable AI" copy="Grad-CAM attention and lesion maps show why a grade was assigned." /><Capability icon={<Gauge />} title="Confidence-aware Referral" copy="Unsafe or uncertain cases are deferred to a doctor." /><Capability icon={<CloudOff />} title="Offline-first Screening" copy="The full workflow runs on-device and syncs when connected." /></div></section>
      </div>
    </div>
  );
}

function Sidebar({ view, onNavigate, mobileNav, onClose }: { view: View; onNavigate: (view: View) => void; mobileNav: boolean; onClose: () => void }) {
  return <aside className={`${mobileNav ? "fixed inset-3 z-40 flex" : "hidden lg:flex"} frosted spec-border w-64 shrink-0 flex-col rounded-[20px] p-4`}><div className="flex items-center justify-between"><Brand /><button onClick={onClose} className="rounded-lg p-2 text-mute hover:bg-primary/5 lg:hidden" aria-label="Close navigation"><X className="size-4" /></button></div><nav className="mt-6 space-y-1 text-sm">{navItems.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => onNavigate(id)} className={`flex w-full items-center gap-3 rounded-[11px] px-3 py-2.5 text-left transition ${view === id ? "bg-primary/5 font-medium text-navy shadow-sm" : "text-ink hover:bg-primary/5"}`}><Icon className={`size-4 ${view === id ? "text-emerald" : "text-mute"}`} />{label}{id === "review" && <span className="ml-auto rounded-full bg-coral/10 px-1.5 py-0.5 text-[10px] text-coral">12</span>}</button>)}</nav><div className="mt-auto pt-4"><div className="rounded-[14px] bg-primary/5 p-3 spec-border"><div className="text-[10px] uppercase tracking-[0.16em] text-mute">AI System Status</div><div className="mt-2.5 space-y-2 text-xs"><StatusLine label="Model" value="Active" good /><StatusLine label="Offline Mode" value="Available" /><StatusLine label="Last Sync" value="Recently" /></div></div><p className="mt-4 px-1 text-[10px] leading-4 text-mute">Screening and clinical decision-support prototype. Not a substitute for diagnosis by a qualified ophthalmologist.</p></div></aside>;
}

function Topbar({ online, onToggle, onMenu }: { online: boolean; onToggle: () => void; onMenu: () => void }) {
  return <header className="frosted spec-border flex items-center gap-3 rounded-[18px] px-4 py-3.5 sm:px-5"><button onClick={onMenu} className="rounded-lg p-2 text-mute hover:bg-primary/5 lg:hidden" aria-label="Open navigation"><Menu className="size-5" /></button><div className="min-w-0"><div className="font-display text-sm font-semibold tracking-tight">PHC Rampur</div><div className="text-[11px] text-mute">Facility · Uttar Pradesh</div></div><div className="ml-auto flex items-center gap-2 sm:gap-3"><button onClick={onToggle} className="flex items-center rounded-full bg-primary/5 p-1 text-xs font-medium" aria-label="Toggle connectivity"><span className={`flex items-center gap-1.5 rounded-full px-3 py-1.5 ${online ? "bg-emerald/15 text-emerald" : "bg-coral/15 text-coral"}`}><span className="size-1.5 rounded-full bg-current" />{online ? "Online" : "Offline Mode"}</span></button><div className="hidden items-center gap-2 rounded-full bg-primary/5 px-3 py-2 text-xs text-ink sm:flex"><Languages className="size-3.5" /> English</div><button className="grid size-9 place-items-center rounded-full bg-primary/5 text-mute" aria-label="Notifications"><Bell className="size-4" /></button><div className="grid size-9 place-items-center rounded-full bg-navy text-xs font-medium text-primary-foreground">AR</div></div></header>;
}

function Overview({ onNavigate, offlineQueue }: { onNavigate: (view: View) => void; offlineQueue: number }) {
  return <div><PageHeader eyebrow="CLINICAL OVERVIEW" title="Good morning, Anjali" copy="Here’s today’s retinal screening activity at PHC Rampur." action={<button onClick={() => onNavigate("screening")} className="inline-flex items-center gap-2 rounded-lg bg-navy px-4 py-2.5 text-sm font-semibold text-primary-foreground"><Plus className="size-4" /> New Screening</button>} /><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6">{[["Total Screenings", "248", "+18 today"], ["Referable DR", "47", "19.0% of total"], ["Pending Reviews", "12", "3 high priority"], ["Retakes Prevented", "31", "+12% this week"], ["Sync Pending", String(offlineQueue), "Stored on device"], ["Avg AI Confidence", "91.4%", "+2.1% this month"]].map(([label, value, trend], index) => <div key={label} className="frosted spec-border rounded-2xl p-4"><div className="text-[10px] uppercase tracking-[0.14em] text-mute">{label}</div><div className="mt-2 font-display text-2xl font-semibold">{value}</div><div className={`mt-1 text-xs font-medium ${index === 1 || index === 2 ? "text-coral" : "text-emerald"}`}>{trend}</div></div>)}</div><div className="mt-4 grid gap-4 xl:grid-cols-[1.35fr_0.8fr_0.8fr]"><Panel title="Screening Activity" action="Last 7 days"><div className="flex h-48 items-end gap-3 border-b border-primary/10 px-2 pb-1 pt-5">{[42, 54, 38, 66, 52, 77, 68].map((value, index) => <div key={index} className="flex flex-1 flex-col items-center gap-2"><div className="w-full max-w-8 rounded-t-md bg-emerald/60 transition hover:bg-emerald" style={{ height: `${value * 1.75}px` }} /><span className="text-[10px] text-mute">{["M", "T", "W", "T", "F", "S", "S"][index]}</span></div>)}</div><div className="mt-3 flex items-center justify-between text-xs text-mute"><span><span className="mr-1.5 inline-block size-2 rounded-full bg-emerald" />Daily screenings</span><strong className="font-medium text-ink">248 total</strong></div></Panel><Panel title="DR Grade Distribution"><div className="mt-3 flex items-center gap-4"><div className="relative grid size-32 shrink-0 place-items-center rounded-full" style={{ background: "conic-gradient(var(--color-emerald) 0 42%, var(--color-teal) 42% 62%, var(--color-amber) 62% 79%, var(--color-coral) 79% 92%, var(--color-navy) 92% 100%)" }}><div className="grid size-20 place-items-center rounded-full bg-surface text-center"><strong className="font-display text-xl">248</strong><span className="text-[10px] text-mute">cases</span></div></div><div className="space-y-2 text-xs">{[["No DR", "42%", "bg-emerald"], ["Mild", "20%", "bg-teal"], ["Moderate", "17%", "bg-amber"], ["Severe", "13%", "bg-coral"], ["PDR", "8%", "bg-navy"]].map(([label, value, color]) => <div key={label} className="flex items-center gap-2"><span className={`size-2 rounded-full ${color}`} /><span className="w-16 text-ink">{label}</span><strong>{value}</strong></div>)}</div></div></Panel><Panel title="Referral Status"><div className="mt-4 space-y-3 text-xs">{[["Routine", "132", "bg-emerald", "53%"], ["Refer", "74", "bg-amber", "30%"], ["Urgent", "18", "bg-coral", "7%"], ["Human Review", "24", "bg-navy", "10%"]].map(([label, value, color, width]) => <div key={label}><div className="flex justify-between"><span>{label}</span><strong>{value}</strong></div><div className="mt-1.5 h-1.5 rounded-full bg-primary/10"><div className={`h-full rounded-full ${color}`} style={{ width }} /></div></div>)}</div></Panel></div><div className="mt-4 grid gap-4 xl:grid-cols-[1fr_0.42fr]"><Panel title="Recent Screenings" action="View all"><ScreeningTable records={initialRecords.slice(0, 4)} compact /></Panel><div className="frosted spec-border rounded-2xl bg-emerald/5 p-5"><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-emerald/15 text-emerald"><CloudOff className="size-5" /></div><div><h3 className="font-display font-semibold">Offline queue</h3><p className="text-xs text-mute">Ready when you are</p></div></div><div className="mt-5 font-display text-4xl font-semibold">{offlineQueue}</div><p className="mt-1 text-sm text-ink">screenings waiting to sync</p><button onClick={() => onNavigate("offline")} className="mt-5 inline-flex items-center gap-2 text-sm font-semibold text-emerald">View Offline Queue <ArrowRight className="size-4" /></button></div></div></div>;
}

function ScreeningWorkspace({ scenario, result, step, setStep, viewer, setViewer, lowConcordance, setLowConcordance, poorCapture, setPoorCapture, analyzing, runAnalysis, online, onCompleteOffline, onReport, chooseScenario }: { scenario: Scenario; result: typeof scenarios[Scenario]; step: ScreeningStep; setStep: (step: ScreeningStep) => void; viewer: ViewerMode; setViewer: (mode: ViewerMode) => void; lowConcordance: boolean; setLowConcordance: (value: boolean) => void; poorCapture: boolean; setPoorCapture: (value: boolean) => void; analyzing: boolean; runAnalysis: () => void; online: boolean; onCompleteOffline: () => void; onReport: () => void; chooseScenario: (scenario: Scenario) => void }) {
  const steps: { id: ScreeningStep; label: string }[] = [{ id: "patient", label: "Patient" }, { id: "capture", label: "Capture" }, { id: "quality", label: "Quality Check" }, { id: "analysis", label: "AI Analysis" }, { id: "explainability", label: "Explainability" }, { id: "referral", label: "Referral" }];
  const activeIndex = steps.findIndex((item) => item.id === step);
  const goNext = () => { const next = steps[Math.min(activeIndex + 1, steps.length - 1)]; if (next) setStep(next.id); };
  const goBack = () => { const previous = steps[activeIndex - 1]; if (previous) setStep(previous.id); };
  return <div><PageHeader eyebrow="NEW SCREENING · DR-2026-00142" title={step === "patient" ? "Start a safe retinal screening" : "Retinal capture & explainability"} copy="Sunita Devi · 54 · Shivpura · ICDR screening journey" action={<ScenarioMenu value={scenario} onChange={chooseScenario} />} /><div className="mb-4 flex gap-2 overflow-x-auto pb-1">{steps.map((item, index) => <button key={item.id} onClick={() => setStep(item.id)} disabled={index > activeIndex} aria-current={index === activeIndex ? "step" : undefined} className={`flex min-w-max items-center gap-2 rounded-full px-3 py-2 text-xs font-medium transition disabled:cursor-not-allowed disabled:opacity-50 ${index <= activeIndex ? "bg-emerald/15 text-emerald" : "bg-primary/5 text-mute"}`}><span className={`grid size-5 place-items-center rounded-full text-[10px] ${index < activeIndex ? "bg-emerald text-primary-foreground" : index === activeIndex ? "bg-emerald/20 text-emerald" : "bg-primary/10"}`}>{index < activeIndex ? <Check className="size-3" /> : index + 1}</span>{item.label}</button>)}</div>{step === "patient" && <PatientStep onNext={goNext} />}{step === "capture" && <CaptureStep onNext={goNext} onBack={goBack} onPoor={() => { setPoorCapture(true); setStep("quality"); }} />}{step === "quality" && <QualityStep poor={poorCapture} onRetake={() => { setPoorCapture(false); setStep("capture"); }} onBack={goBack} onNext={() => { if (poorCapture) return; setStep("analysis"); }} />}{step === "analysis" && <AnalysisStep analyzing={analyzing} onAnalyze={runAnalysis} onBack={goBack} onNext={() => setStep("explainability")} />}{(step === "explainability" || step === "referral") && <ResultStep result={result} viewer={viewer} setViewer={setViewer} lowConcordance={lowConcordance} setLowConcordance={setLowConcordance} onBack={goBack} onReferral={() => setStep("referral")} onReport={onReport} online={online} onCompleteOffline={onCompleteOffline} step={step} />}</div>;
}

function PatientStep({ onNext }: { onNext: () => void }) { return <div className="grid gap-4 xl:grid-cols-[1fr_0.72fr]"><Panel title="Patient details" subtitle="Optional fields can be completed later"><div className="grid gap-4 sm:grid-cols-2">{[["Patient ID", "DR-2026-00142"], ["Patient name", "Sunita Devi"], ["Age", "54"], ["Village", "Shivpura"], ["Phone number", "+91 98••• ••42"], ["Last eye examination", "Over 1 year ago"]].map(([label, value]) => <label key={label} className="space-y-1.5 text-sm"><span className="text-xs font-medium text-ink">{label}</span><input defaultValue={value} className="w-full rounded-lg border border-primary/10 bg-primary/5 px-3 py-2.5 text-sm text-navy outline-none focus:ring-2 focus:ring-ring/30" /></label>)}</div><div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="space-y-1.5 text-sm"><span className="text-xs font-medium text-ink">Known diabetes</span><select defaultValue="Yes" className="w-full rounded-lg border border-primary/10 bg-primary/5 px-3 py-2.5 text-sm"><option>Yes</option><option>No</option><option>Unknown</option></select></label><label className="space-y-1.5 text-sm"><span className="text-xs font-medium text-ink">Diabetes duration</span><select defaultValue="6–10 years" className="w-full rounded-lg border border-primary/10 bg-primary/5 px-3 py-2.5 text-sm"><option>Less than 5 years</option><option>6–10 years</option><option>More than 10 years</option></select></label></div><div className="mt-6 flex justify-end"><PrimaryButton onClick={onNext}>Continue to Retinal Capture <ArrowRight className="size-4" /></PrimaryButton></div></Panel><div className="frosted spec-border rounded-2xl p-5"><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-emerald/15 text-emerald"><HeartPulse className="size-5" /></div><div><h3 className="font-display font-semibold">A simple first step</h3><p className="text-xs text-mute">Designed for frontline health workers</p></div></div><ul className="mt-5 space-y-3 text-sm text-ink"><li className="flex gap-2"><CheckCircle2 className="mt-0.5 size-4 shrink-0 text-emerald" />No diagnosis is made from patient details alone.</li><li className="flex gap-2"><CheckCircle2 className="mt-0.5 size-4 shrink-0 text-emerald" />Every scan receives an image quality check.</li><li className="flex gap-2"><CheckCircle2 className="mt-0.5 size-4 shrink-0 text-emerald" />Uncertain cases are safely routed to review.</li></ul></div></div>; }

function CaptureStep({ onNext, onBack, onPoor }: { onNext: () => void; onBack: () => void; onPoor: () => void }) { const [source, setSource] = useState("Sample fundus image ready"); return <div className="grid gap-4 xl:grid-cols-[1fr_0.72fr]"><Panel title="Retinal capture" subtitle="Center the optic disc inside the guide before capturing"><div className="retina-scan grid aspect-[1.35] place-items-center overflow-hidden rounded-2xl bg-navy/90"><div className="grid-lines absolute inset-0 opacity-30" /><div className="relative size-60 overflow-hidden rounded-full border border-primary-foreground/30 shadow-2xl sm:size-72"><img src={fundusImage} alt="Sample retinal fundus image" width={1024} height={1024} className="size-full object-cover" /></div><div className="absolute bottom-4 rounded-full bg-navy/70 px-3 py-1.5 text-xs text-primary-foreground">Align the retina within the circle</div></div><div className="mt-4 flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2 text-xs text-mute"><ScanLine className="size-4 text-emerald" /> {source}</div><div className="flex flex-wrap justify-end gap-2"><button onClick={onBack} className="rounded-lg border border-primary/10 bg-primary/5 px-3 py-2 text-xs font-semibold text-ink">Back</button><button onClick={onPoor} className="rounded-lg border border-coral/20 px-3 py-2 text-xs font-medium text-coral hover:bg-coral/5">Simulate Poor Capture</button><label className="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-primary/10 bg-primary/5 px-3 py-2 text-xs font-semibold text-ink"><Upload className="size-3.5" /> Upload image<input type="file" accept="image/*" className="sr-only" onChange={(event) => { const file = event.target.files?.[0]; if (file) setSource(file.name); }} /></label><button onClick={onNext} className="inline-flex items-center gap-2 rounded-lg bg-navy px-4 py-2.5 text-sm font-semibold text-primary-foreground"><ArrowRight className="size-4" /> Run quality check</button></div></div></Panel><div className="frosted spec-border rounded-2xl p-5"><h3 className="font-display font-semibold">Capture guidance</h3><div className="mt-4 space-y-3 text-sm text-ink"><Guidance icon={<ScanLine />} text="Keep the camera stable and level." /><Guidance icon={<Eye />} text="Move closer until the retina fills the guide." /><Guidance icon={<AlertTriangle />} text="Avoid direct glare from windows or lights." /></div><div className="mt-5 rounded-xl bg-emerald/10 p-3 text-xs leading-5 text-ink"><strong className="text-emerald">Demo-ready:</strong> Use the sample image or upload a retinal image. Both paths run through the same quality gate.</div></div></div>; }

function QualityStep({ poor, onRetake, onBack, onNext }: { poor: boolean; onRetake: () => void; onBack: () => void; onNext: () => void }) { const checks = poor ? [["Blur", 32], ["Exposure", 88], ["Glare", 95], ["Field of View", 61]] : [["Blur", 92], ["Exposure", 88], ["Glare", 95], ["Field of View", 90]]; return <div className="grid gap-4 xl:grid-cols-[1fr_0.72fr]"><Panel title="On-device quality gate" subtitle="Inference is blocked until the image is safe to interpret"><div className={`rounded-xl p-4 ${poor ? "bg-coral/10" : "bg-emerald/10"}`}><div className="flex items-center gap-3">{poor ? <AlertTriangle className="size-5 text-coral" /> : <CheckCircle2 className="size-5 text-emerald" />}<div><p className="font-display font-semibold">{poor ? "Image rejected" : "Image Quality: Good"}</p><p className="mt-0.5 text-xs text-ink">{poor ? "Image is too blurry for reliable screening." : "All four checks passed. Safe to continue."}</p></div></div></div><div className="mt-5 space-y-4">{checks.map(([label, score]) => <div key={label}><div className="flex justify-between text-sm"><span className="flex items-center gap-2"><span className={`size-2 rounded-full ${Number(score) < 70 ? "bg-coral" : "bg-emerald"}`} />{label}</span><strong>{score}%</strong></div><div className="mt-1.5 h-2 rounded-full bg-primary/10"><div className={`h-full rounded-full ${Number(score) < 70 ? "bg-coral" : "bg-emerald"}`} style={{ width: `${score}%` }} /></div></div>)}</div>{poor ? <div className="mt-5 rounded-xl border border-coral/20 bg-coral/5 p-4 text-sm"><p className="font-semibold text-coral">Recommendation: Retake image</p><p className="mt-1 text-xs leading-5 text-ink">Keep the camera stable, move closer and center the retina. The classifier will not run on this capture.</p><button onClick={onRetake} className="mt-3 rounded-lg bg-coral/10 px-3 py-2 text-xs font-semibold text-coral">Retake Image</button></div> : <div className="mt-5 flex justify-end gap-2"><button onClick={onBack} className="rounded-lg border border-primary/10 bg-primary/5 px-3 py-2.5 text-xs font-semibold text-ink">Back to capture</button><PrimaryButton onClick={onNext}>Continue to AI Analysis <ArrowRight className="size-4" /></PrimaryButton></div>}</Panel><div className="frosted spec-border rounded-2xl p-5"><div className="flex items-center gap-2 text-sm font-semibold"><ShieldCheck className="size-4 text-emerald" /> Why this gate matters</div><p className="mt-3 text-sm leading-6 text-ink">A poor photograph can make a confident model wrong. DrishtiAI rejects blurry, overexposed or poorly centered images before disease classification starts.</p><div className="mt-5 rounded-xl bg-primary/5 p-3 text-xs text-mute"><Info className="mr-1 inline size-3.5" /> Quality scoring runs locally, even in Offline Mode.</div></div></div>; }

function AnalysisStep({ analyzing, onAnalyze, onNext }: { analyzing: boolean; onAnalyze: () => void; onNext: () => void }) { const substeps = ["Preprocessing retinal image", "Detecting retinal features", "Estimating DR grade", "Detecting lesions", "Generating explanation", "Calculating reasoning confidence"]; return <div className="grid gap-4 xl:grid-cols-[1fr_0.72fr]"><Panel title="AI analysis" subtitle="A transparent sequence, not a black box"><div className="flex min-h-64 flex-col items-center justify-center rounded-xl bg-primary/5 p-6 text-center"><div className={`grid size-16 place-items-center rounded-full bg-emerald/15 text-emerald ${analyzing ? "soft-pulse" : ""}`}>{analyzing ? <RefreshCw className="size-7 animate-spin" /> : <Microscope className="size-7" />}</div><h3 className="mt-4 font-display text-xl font-semibold">{analyzing ? "Analyzing retinal image…" : "Ready to run explainable analysis"}</h3><p className="mt-1 max-w-sm text-sm text-mute">The demo model will classify the image, detect lesions, and compare attention against lesion regions.</p>{!analyzing && <PrimaryButton onClick={onAnalyze} className="mt-5"><Play className="size-4" /> Run AI Analysis</PrimaryButton>}</div><div className="mt-5 grid gap-2 sm:grid-cols-2">{substeps.map((item, index) => <div key={item} className={`flex items-center gap-2 rounded-lg border border-primary/10 px-3 py-2.5 text-xs ${analyzing && index < 4 ? "bg-emerald/10 text-emerald" : "bg-primary/5 text-ink"}`}>{analyzing && index < 4 ? <Check className="size-3.5" /> : <span className="grid size-4 place-items-center rounded-full bg-primary/10 text-[9px]">{index + 1}</span>}{item}</div>)}</div>{!analyzing && <div className="mt-5 flex justify-end"><button onClick={onNext} className="text-sm font-semibold text-emerald">Skip to demo result <ArrowRight className="ml-1 inline size-4" /></button></div>}</Panel><div className="frosted spec-border rounded-2xl p-5"><div className="flex items-center gap-2 text-sm font-semibold"><BadgeCheck className="size-4 text-emerald" /> Safe reporting thresholds</div><div className="mt-4 space-y-3 text-sm text-ink"><StatusLine label="AI confidence threshold" value="≥ 80%" /><StatusLine label="Reasoning threshold" value="≥ 60%" /><StatusLine label="Quality gate" value="Required" /></div><p className="mt-5 text-xs leading-5 text-mute">If any threshold is unsafe, the result is withheld and routed to an ophthalmologist.</p></div></div>; }

function ResultStep({ result, viewer, setViewer, lowConcordance, setLowConcordance, onReferral, onReport, online, onCompleteOffline, step }: { result: typeof scenarios[Scenario]; viewer: ViewerMode; setViewer: (mode: ViewerMode) => void; lowConcordance: boolean; setLowConcordance: (value: boolean) => void; onReferral: () => void; onReport: () => void; online: boolean; onCompleteOffline: () => void; step: ScreeningStep }) { const low = lowConcordance || result.reasoning === 28; const grade = result.grade; return <div><div className="grid gap-4 xl:grid-cols-[1.2fr_0.8fr]"><Panel title="Retinal evidence" subtitle="Inspect the evidence before accepting the referral"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex flex-wrap gap-1 rounded-full bg-primary/5 p-1">{(["original", "gradcam", "lesions", "combined"] as ViewerMode[]).map((mode) => <button key={mode} onClick={() => setViewer(mode)} className={`rounded-full px-3 py-1.5 text-xs font-medium capitalize ${viewer === mode ? "bg-emerald/15 text-emerald" : "text-mute"}`}>{mode === "gradcam" ? "Grad-CAM" : mode}</button>)}</div><span className="text-xs text-mute">Fundus image · left eye</span></div><RetinaViewer mode={viewer} /><div className="mt-4 grid gap-2 text-xs sm:grid-cols-3"><Legend color="bg-coral" label="Microaneurysms" /><Legend color="bg-navy" label="Hemorrhages" /><Legend color="bg-teal" label="Exudates" /></div></Panel><div className="space-y-4"><div className="frosted spec-border rounded-2xl p-5"><div className="flex items-start justify-between"><div><h3 className="font-display text-lg font-semibold">Why did the AI make this decision?</h3><p className="mt-1 text-xs text-mute">Clinical explanation from attention + lesion evidence</p></div><CircleHelp className="size-4 text-mute" /></div><p className="mt-4 text-sm leading-6 text-ink">{low ? "The model is highly confident in its prediction, but its attention does not sufficiently overlap with clinically relevant lesion regions. This case has been deferred for ophthalmologist review." : `The model identified multiple small hemorrhagic and microaneurysm-like regions around the upper temporal retina. Their distribution is consistent with ${grade.toLowerCase()} diabetic retinopathy.`}</p><div className="mt-4 flex items-center gap-2 rounded-xl bg-primary/5 p-3 text-xs"><span className="rounded-md bg-emerald/15 px-2 py-1 font-medium text-emerald">Attention</span><span className="text-mute">+</span><span className="rounded-md bg-emerald/15 px-2 py-1 font-medium text-emerald">Lesions</span><ArrowRight className="size-3 text-mute" /><strong className="ml-auto">IoU {low ? "0.21" : "0.74"}</strong></div></div><ConcordanceCard low={low} confidence={result.confidence} onToggle={() => setLowConcordance(!lowConcordance)} /></div></div><div className="mt-4 grid gap-4 lg:grid-cols-[0.8fr_1.2fr]"><ReferralCard grade={grade} low={low} referral={low ? "DEFERRED" : result.referral.toUpperCase()} /><div className="frosted spec-border rounded-2xl p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-display font-semibold">Probability distribution</h3><p className="mt-1 text-xs text-mute">Five-class ICDR output</p></div><span className="text-xs text-mute">{result.confidence ? `${result.confidence}% model confidence` : "AI result withheld"}</span></div><div className="mt-5 space-y-3">{[["No DR", grade === "No DR" ? 97 : 2], ["Mild", grade === "Mild" ? 89 : 4], ["Moderate", grade === "Moderate" ? 93 : 1], ["Severe", grade === "Severe" ? 96 : 1], ["Proliferative", 0]].map(([label, value]) => <div key={label} className="flex items-center gap-3 text-xs"><span className="w-20 text-ink">{label}</span><div className="h-2 flex-1 rounded-full bg-primary/10"><div className={`h-full rounded-full ${label === grade ? "bg-emerald" : "bg-primary/20"}`} style={{ width: `${value}%` }} /></div><strong className="w-8 text-right">{value}%</strong></div>)}</div></div></div><div className="mt-4 flex flex-wrap justify-end gap-2"><button onClick={onReport} className="inline-flex items-center gap-2 rounded-lg border border-primary/10 bg-primary/5 px-4 py-2.5 text-sm font-semibold"><FileText className="size-4" /> Dual-audience report</button>{step === "explainability" && <button onClick={onReferral} className="inline-flex items-center gap-2 rounded-lg bg-navy px-4 py-2.5 text-sm font-semibold text-primary-foreground">Review referral <ArrowRight className="size-4" /></button>}{step === "referral" && <button onClick={online ? onReport : onCompleteOffline} className="inline-flex items-center gap-2 rounded-lg bg-emerald px-4 py-2.5 text-sm font-semibold text-primary-foreground">{online ? "Complete screening" : "Save locally"} <Check className="size-4" /></button>}</div></div>; }

function RetinaViewer({ mode, large = false }: { mode: ViewerMode; large?: boolean }) { return <div className={`retina-scan relative mt-4 mx-auto aspect-square overflow-hidden rounded-full bg-navy ${large ? "max-w-[390px]" : "max-w-[440px]"}`}><img src={fundusImage} alt="Retinal fundus scan used for demonstration" width={1024} height={1024} className="size-full object-cover" loading={large ? undefined : "lazy"} /><div className={`absolute inset-0 ${mode === "gradcam" || mode === "combined" ? "heatmap" : ""}`} />{(mode === "lesions" || mode === "combined") && <><span className="absolute left-[65%] top-[28%] size-4 rounded-full border-2 border-coral bg-coral/30" /><span className="absolute left-[73%] top-[38%] size-3 rounded-full border-2 border-coral bg-coral/30" /><span className="absolute left-[57%] top-[47%] size-3 rounded-full border-2 border-amber bg-amber/30" /><span className="absolute left-[42%] top-[55%] size-3 rounded-full border-2 border-navy bg-navy/30" /></>}</div>; }

function ConcordanceCard({ low, confidence, onToggle }: { low: boolean; confidence: number; onToggle: () => void }) { return <div className={`frosted spec-border rounded-2xl p-5 ${low ? "bg-coral/5" : ""}`}><div className="flex items-start justify-between"><div><h3 className="font-display text-lg font-semibold">Reasoning Confidence</h3><p className="mt-1 text-xs text-mute">Does the AI focus on clinically meaningful lesion regions?</p></div><span className={`rounded-full px-2.5 py-1 text-[11px] font-medium ${low ? "bg-coral/15 text-coral" : "bg-emerald/15 text-emerald"}`}>{low ? "Human Review Required" : "Strong Alignment"}</span></div><div className="mt-5 flex items-center gap-5"><div className="relative grid size-24 shrink-0 place-items-center rounded-full" style={{ background: `conic-gradient(var(--color-${low ? "coral" : "emerald"}) 0 ${low ? 28 : 87}%, color-mix(in oklab, var(--color-navy) 8%, transparent) ${low ? 28 : 87}% 100%)` }}><div className="grid size-16 place-items-center rounded-full bg-surface"><strong className="font-display text-2xl">{low ? 28 : 87}<span className="text-sm text-mute">%</span></strong></div></div><div className="flex-1 space-y-2 text-xs"><div className="flex justify-between"><span>AI Classification</span><strong>{confidence}%</strong></div><div className="flex justify-between"><span>Lesion-Attention</span><strong className={low ? "text-coral" : "text-emerald"}>{low ? 28 : 87}%</strong></div><div className="flex gap-2 pt-1"><span className="rounded-md bg-primary/5 px-2 py-1 text-mute">IoU {low ? "0.21" : "0.74"}</span><span className="rounded-md bg-primary/5 px-2 py-1 text-mute">Dice {low ? "0.36" : "0.85"}</span></div></div></div><p className="mt-4 text-xs leading-5 text-ink">{low ? "High diagnosis confidence but low reasoning alignment. The model may have found the right answer for the wrong reason." : "The areas highlighted by Grad-CAM significantly overlap with detected retinal lesion regions."}</p><button onClick={onToggle} className="mt-4 text-xs font-semibold text-coral">{low ? "Restore strong concordance" : "Simulate Low Concordance"}</button></div>; }

function ReferralCard({ grade, low, referral }: { grade: string; low: boolean; referral: string }) { return <div className={`frosted spec-border rounded-2xl p-5 ${low ? "border border-coral/20" : ""}`}><div className="flex items-center justify-between"><h3 className="font-display font-semibold">Referral Decision</h3><span className={`rounded-full px-2.5 py-1 text-[11px] font-medium ${low ? "bg-coral/15 text-coral" : "bg-amber/20 text-amber-foreground"}`}>{referral}</span></div><p className="mt-4 font-display text-xl font-semibold">{low ? "Human review required" : grade === "No DR" ? "Routine screening" : "Refer to Ophthalmologist"}</p><p className="mt-1 text-sm leading-6 text-ink">{low ? "AI result withheld because reasoning confidence is below the safe reporting threshold." : `${grade} DR detected with high lesion burden. Review the evidence before communicating this result.`}</p><div className={`mt-4 rounded-xl p-3 text-xs leading-5 ${low ? "bg-coral/10 text-coral" : "bg-emerald/10 text-ink"}`}><strong>Recommended action:</strong> {low ? "Route to ophthalmologist review queue." : grade === "No DR" ? "Continue routine annual screening." : "Schedule ophthalmology review within 3 months."}</div></div>; }

function Records({ records, search, setSearch, onOpen }: { records: RecordItem[]; search: string; setSearch: (value: string) => void; onOpen: () => void }) { const filtered = useMemo(() => records.filter((item) => `${item.id} ${item.patient} ${item.village}`.toLowerCase().includes(search.toLowerCase())), [records, search]); return <div><PageHeader eyebrow="SCREENING RECORDS" title="A searchable screening history" copy="Synthetic records from PHC Rampur and nearby villages." action={<button className="inline-flex items-center gap-2 rounded-lg border border-primary/10 bg-primary/5 px-4 py-2.5 text-sm font-semibold"><Download className="size-4" /> Export</button>} /><div className="frosted spec-border rounded-2xl p-4"><div className="flex flex-wrap gap-2"><div className="relative min-w-[240px] flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-mute" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search patient ID or village" className="w-full rounded-lg border border-primary/10 bg-primary/5 py-2.5 pl-9 pr-3 text-sm outline-none focus:ring-2 focus:ring-ring/30" /></div>{["All grades", "All referrals", "All sync statuses"].map((filter) => <button key={filter} className="rounded-lg border border-primary/10 bg-primary/5 px-3 py-2.5 text-xs text-ink">{filter} <ChevronRight className="ml-1 inline size-3 rotate-90" /></button>)}</div><div className="mt-4 overflow-x-auto"><ScreeningTable records={filtered} onOpen={onOpen} /></div></div></div>; }

function ScreeningTable({ records, compact = false, onOpen }: { records: RecordItem[]; compact?: boolean; onOpen?: () => void }) { return <table className="w-full min-w-[720px] text-left text-xs"><thead className="border-b border-primary/10 text-[10px] uppercase tracking-[0.12em] text-mute"><tr><th className="px-3 py-3 font-medium">Patient</th><th className="px-3 py-3 font-medium">Village / Date</th><th className="px-3 py-3 font-medium">DR Grade</th><th className="px-3 py-3 font-medium">AI / Reasoning</th><th className="px-3 py-3 font-medium">Referral</th><th className="px-3 py-3 font-medium">Sync</th></tr></thead><tbody>{records.map((record) => <tr key={record.id} onClick={onOpen} className={`${onOpen ? "cursor-pointer hover:bg-primary/5" : ""} border-b border-primary/5 last:border-0`}><td className="px-3 py-3"><div className="font-medium text-navy">{record.id}</div><div className="mt-1 text-mute">{record.patient}</div></td><td className="px-3 py-3"><div>{record.village}</div><div className="mt-1 text-mute">{record.date}</div></td><td className="px-3 py-3"><span className={`rounded-full px-2 py-1 ${record.grade === "No DR" ? "bg-emerald/10 text-emerald" : record.grade === "Severe" ? "bg-coral/10 text-coral" : "bg-amber/15 text-ink"}`}>{record.grade}</span></td><td className="px-3 py-3"><div>{record.confidence}%</div><div className={`mt-1 ${record.reasoning < 60 ? "text-coral" : "text-emerald"}`}>{record.reasoning}% alignment</div></td><td className="px-3 py-3"><span className={`${record.referral === "Review" ? "text-coral" : record.referral === "Routine" ? "text-emerald" : "text-amber-foreground"}`}>{record.referral}</span></td><td className="px-3 py-3"><span className="flex items-center gap-1.5 text-mute"><span className={`size-1.5 rounded-full ${record.sync === "Waiting" ? "bg-amber" : "bg-emerald"}`} />{record.sync}</span></td></tr>)}</tbody></table>; }

function ReviewQueue({ reviewed, setReviewed, onOpen }: { reviewed: boolean; setReviewed: (value: boolean) => void; onOpen: () => void }) { return <div><PageHeader eyebrow="OPHTHALMOLOGIST REVIEW QUEUE" title="Cases that need a human eye" copy="Confidence and concordance keep unsafe cases out of autonomous reporting." action={<span className="rounded-full bg-coral/10 px-3 py-2 text-xs font-semibold text-coral">12 pending reviews</span>} /><div className="grid gap-4 xl:grid-cols-[1fr_0.72fr]"><div className="space-y-3">{[["DR-2026-00140", "Meena Bai", "Severe", "96%", "28%", "High-confidence / low concordance", "High"], ["DR-2026-00136", "Suresh Pal", "Moderate", "71%", "64%", "Low AI confidence", "Medium"], ["DR-2026-00133", "Rekha Kumari", "Mild", "84%", "52%", "Borderline reasoning", "Medium"]].map(([id, patient, grade, confidence, reasoning, reason, priority]) => <button key={id} onClick={() => { onOpen(); setReviewed(false); }} className="frosted spec-border flex w-full items-center gap-4 rounded-2xl p-4 text-left transition hover:-translate-y-0.5"><img src={fundusImage} alt="Retinal case thumbnail" className="size-16 rounded-xl object-cover" /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><strong className="text-sm">{id}</strong><span className="rounded-full bg-coral/10 px-2 py-0.5 text-[10px] text-coral">{priority} priority</span></div><p className="mt-1 text-xs text-mute">{patient} · {grade} · {reason}</p><div className="mt-2 flex gap-4 text-xs"><span>AI {confidence}</span><span className="text-coral">Concordance {reasoning}</span></div></div><ChevronRight className="size-4 text-mute" /></button>)}</div><div className="frosted spec-border rounded-2xl p-5"><div className="flex items-center gap-2 text-sm font-semibold"><Stethoscope className="size-4 text-emerald" /> Review controls</div><p className="mt-3 text-sm leading-6 text-ink">Open a case to compare the original, Grad-CAM, lesion map and combined explanation before confirming or correcting the AI result.</p><div className="mt-5 space-y-3 text-xs"><StatusLine label="High-confidence / low-concordance" value="7 cases" /><StatusLine label="Low-confidence deferred" value="12 cases" /><StatusLine label="Model disagreement" value="3 cases" /></div><div className="mt-5 rounded-xl bg-primary/5 p-3 text-xs leading-5 text-mute"><Info className="mr-1 inline size-3.5" /> Doctor corrections are saved as feedback for future model improvement.</div></div></div>{reviewed && <div className="mt-4 rounded-xl bg-emerald/10 p-4 text-sm text-emerald"><CheckCircle2 className="mr-2 inline size-4" /> Correction saved for future model improvement.</div>}</div>; }

function OfflineSync({ online, queue, syncing, progress, onSync }: { online: boolean; queue: number; syncing: boolean; progress: number; onSync: () => void }) { return <div><PageHeader eyebrow="OFFLINE-FIRST SCREENING" title="Work safely without a signal" copy="Screenings are stored securely on this device and sync when connectivity returns." action={<span className={`rounded-full px-3 py-2 text-xs font-semibold ${online ? "bg-emerald/15 text-emerald" : "bg-coral/15 text-coral"}`}>{online ? "Connection restored" : "Offline Mode"}</span>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[["Connectivity", online ? "Online" : "Offline", online ? "bg-emerald" : "bg-coral"], ["Queued Screenings", String(queue), "bg-amber"], ["Last Successful Sync", "2 hours ago", "bg-emerald"], ["Local Storage", "Healthy", "bg-emerald"]].map(([label, value, color]) => <div key={label} className="frosted spec-border rounded-2xl p-4"><div className="text-[10px] uppercase tracking-[0.14em] text-mute">{label}</div><div className="mt-3 flex items-center gap-2 font-display text-xl font-semibold"><span className={`size-2 rounded-full ${color}`} />{value}</div></div>)}</div><div className="mt-4 grid gap-4 xl:grid-cols-[1fr_0.55fr]"><Panel title="Sync queue" subtitle="Records waiting to reach the clinical dashboard" action={<button onClick={onSync} disabled={!online || syncing || queue === 0} className="inline-flex items-center gap-2 rounded-lg bg-navy px-3 py-2 text-xs font-semibold text-primary-foreground disabled:cursor-not-allowed disabled:opacity-40"><RefreshCw className={`size-3.5 ${syncing ? "animate-spin" : ""}`} /> {syncing ? `Uploading ${Math.min(progress + 1, queue)}/${queue}` : "Sync Now"}</button>}><div className="overflow-x-auto"><table className="w-full min-w-[520px] text-left text-xs"><thead className="border-b border-primary/10 text-[10px] uppercase tracking-[0.12em] text-mute"><tr><th className="py-3 font-medium">Patient ID</th><th className="py-3 font-medium">Timestamp</th><th className="py-3 font-medium">Size</th><th className="py-3 font-medium">Status</th></tr></thead><tbody>{Array.from({ length: Math.min(queue, 5) }, (_, index) => <tr key={index} className="border-b border-primary/5"><td className="py-3 font-medium">DR-2026-{String(146 - index).padStart(5, "0")}</td><td className="py-3 text-mute">Today, {10 - index}:2{index}</td><td className="py-3 text-mute">2.4 MB</td><td className="py-3 text-amber-foreground">{syncing && index < progress ? "Synced" : "Waiting to sync"}</td></tr>)}</tbody></table></div>{syncing && <div className="mt-4 h-2 rounded-full bg-primary/10"><div className="h-full rounded-full bg-emerald transition-all" style={{ width: `${(progress / Math.max(queue, 1)) * 100}%` }} /></div>}</Panel><div className="frosted spec-border rounded-2xl p-5"><div className="grid size-12 place-items-center rounded-xl bg-emerald/15 text-emerald"><Wifi className="size-6" /></div><h3 className="mt-4 font-display text-xl font-semibold">{online ? "Ready to sync" : "Still screening safely"}</h3><p className="mt-2 text-sm leading-6 text-ink">{online ? "When you sync, queued images and referral metadata move to the central review queue." : "The complete screening workflow remains available. Results are stored locally until a connection is restored."}</p></div></div></div>; }

function Analytics() { return <div><PageHeader eyebrow="ANALYTICS" title="Safety monitoring at a glance" copy="Performance signals that matter for a rural screening program." /><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6">{[["Referable DR Rate", "19.0%"], ["Retake Rate", "12.5%"], ["Human Deferral", "4.8%"], ["Avg Confidence", "91.4%"], ["Avg Reasoning", "84.2%"], ["Total Screenings", "248"]].map(([label, value]) => <div key={label} className="frosted spec-border rounded-2xl p-4"><span className="text-[10px] uppercase tracking-[0.14em] text-mute">{label}</span><div className="mt-2 font-display text-2xl font-semibold">{value}</div></div>)}</div><div className="mt-4 grid gap-4 lg:grid-cols-2"><Panel title="Quality failure reasons"><div className="space-y-4 pt-3 text-sm">{[["Blur", 42], ["Glare", 28], ["Exposure", 18], ["Field of View", 12]].map(([label, value]) => <div key={label}><div className="flex justify-between"><span>{label}</span><strong>{value}%</strong></div><div className="mt-2 h-2 rounded-full bg-primary/10"><div className="h-full rounded-full bg-coral" style={{ width: `${value}%` }} /></div></div>)}</div></Panel><Panel title="Confidence vs. concordance"><div className="relative mt-4 h-56 rounded-xl bg-primary/5"><div className="absolute inset-5 border-b border-l border-primary/20" /><div className="absolute left-[22%] top-[65%] size-3 rounded-full bg-coral" /><div className="absolute left-[38%] top-[48%] size-3 rounded-full bg-emerald" /><div className="absolute left-[52%] top-[36%] size-3 rounded-full bg-emerald" /><div className="absolute left-[72%] top-[24%] size-3 rounded-full bg-emerald" /><div className="absolute left-[82%] top-[72%] size-3 rounded-full bg-coral" /><span className="absolute bottom-2 left-1/2 text-[10px] text-mute">Diagnosis confidence →</span><span className="absolute left-2 top-1/2 -rotate-90 text-[10px] text-mute">Reasoning confidence →</span></div></Panel></div><div className="mt-4 rounded-2xl bg-coral/5 p-5 spec-border"><h3 className="font-display font-semibold">Safety monitoring</h3><div className="mt-4 grid gap-4 sm:grid-cols-3"><div><strong className="font-display text-2xl text-coral">7</strong><p className="mt-1 text-xs text-ink">high-confidence / low-concordance cases</p></div><div><strong className="font-display text-2xl text-coral">12</strong><p className="mt-1 text-xs text-ink">low-confidence deferred cases</p></div><div><strong className="font-display text-2xl text-coral">31</strong><p className="mt-1 text-xs text-ink">poor-quality captures rejected</p></div></div></div></div>; }

function ModelInsights() { const flow = ["Fundus Image", "Quality Gate", "Classification", "Grad-CAM + Lesions", "Concordance", "Referral Logic", "Dual Report"]; return <div><PageHeader eyebrow="MODEL INSIGHTS · SIH26038" title="Clinical AI you can inspect" copy="The system architecture makes safety visible from capture to referral." /><div className="frosted spec-border rounded-2xl p-5"><div className="flex flex-wrap items-center justify-center gap-2">{flow.map((item, index) => <div key={item} className="flex items-center gap-2"><div className="rounded-xl bg-primary/5 px-3 py-3 text-center text-xs font-semibold">{item}</div>{index < flow.length - 1 && <ArrowRight className="size-4 text-emerald" />}</div>)}</div></div><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{[["Classification Backbone", "EfficientNet-B3 / B4"], ["Outputs", "5-class ICDR + Referable DR"], ["Explainability", "Grad-CAM++"], ["Lesion Detection", "Lightweight U-Net"], ["Primary Grading Metric", "Quadratic Weighted Kappa"], ["Edge Optimization", "INT8 Quantization"], ["Deployment", "ONNX / MATLAB Coder compatible"], ["Datasets", "APTOS · EyePACS · IDRiD · Messidor-2"], ["Domain Match", "IDRiD lesion supervision"]].map(([label, value]) => <div key={label} className="frosted spec-border rounded-2xl p-4"><div className="text-[10px] uppercase tracking-[0.14em] text-mute">{label}</div><div className="mt-2 font-display font-semibold">{value}</div></div>)}</div><div className="mt-4 grid gap-4 lg:grid-cols-2"><Panel title="Why this system is different"><div className="space-y-3">{[["Quality Before Classification", "Poor captures are rejected before inference."], ["Explainability as Verification", "Attention is checked against detected lesion regions."], ["Uncertainty-aware Safety", "Unsafe cases are deferred rather than auto-reported."], ["Offline-first Deployment", "Designed for low-connectivity rural screening."], ["Dual-audience Explanation", "Clinical detail for doctors, simple language for patients."]].map(([title, copy]) => <div key={title} className="flex gap-3 rounded-xl bg-primary/5 p-3"><CheckCircle2 className="mt-0.5 size-4 shrink-0 text-emerald" /><div><strong className="text-sm">{title}</strong><p className="mt-1 text-xs leading-5 text-mute">{copy}</p></div></div>)}</div></Panel><Panel title="Supported demo scenarios"><div className="space-y-2 text-sm text-ink"><p><span className="mr-2 inline-block size-2 rounded-full bg-emerald" />Healthy Retina · 97% · Routine</p><p><span className="mr-2 inline-block size-2 rounded-full bg-amber" />Moderate DR · 93% · Refer</p><p><span className="mr-2 inline-block size-2 rounded-full bg-coral" />Poor Image · classifier withheld</p><p><span className="mr-2 inline-block size-2 rounded-full bg-navy" />Clever Hans · 96% / 28% · Review</p></div></Panel></div></div>; }

function SettingsPanel() { return <div><PageHeader eyebrow="SETTINGS" title="Demo environment" copy="Keep the presentation focused on safe, explainable screening." /><div className="grid gap-4 lg:grid-cols-2"><Panel title="Facility profile"><div className="space-y-4">{[["Facility", "PHC Rampur"], ["District", "Uttar Pradesh"], ["Primary role", "Health Worker"], ["Default language", "English"]].map(([label, value]) => <div key={label} className="flex items-center justify-between border-b border-primary/10 pb-3 text-sm"><span className="text-mute">{label}</span><strong>{value}</strong></div>)}</div></Panel><Panel title="Clinical safeguards"><div className="space-y-4"><StatusLine label="Show quality gate before AI" value="Enabled" good /><StatusLine label="Require human review on low concordance" value="Enabled" good /><StatusLine label="Store offline queue locally" value="Enabled" good /><StatusLine label="Clinical disclaimer" value="Visible" good /></div></Panel></div></div>; }

function ReportModal({ language, setLanguage, onClose, onDownload }: { language: string; setLanguage: (value: string) => void; onClose: () => void; onDownload: () => void }) { const hindi = language === "हिन्दी"; return <div className="fixed inset-0 z-50 grid place-items-center bg-navy/30 p-4 backdrop-blur-sm"><div role="dialog" aria-modal="true" className="max-h-[90vh] w-full max-w-3xl overflow-y-auto rounded-2xl bg-surface p-5 shadow-2xl sm:p-7"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-emerald">DUAL-AUDIENCE REPORT</p><h2 className="mt-1 font-display text-2xl font-semibold">{hindi ? "आंखों की जांच का परिणाम" : "Eye screening result"}</h2></div><button onClick={onClose} className="rounded-lg p-2 text-mute hover:bg-primary/5" aria-label="Close report"><X className="size-5" /></button></div><div className="mt-5 flex gap-1 rounded-lg bg-primary/5 p-1"><button className="flex-1 rounded-md bg-surface px-3 py-2 text-xs font-semibold">{hindi ? "स्वास्थ्यकर्मी / रोगी" : "Patient / Health Worker"}</button><button className="flex-1 rounded-md px-3 py-2 text-xs text-mute">Clinical View</button></div><div className="mt-5 grid gap-4 md:grid-cols-[0.7fr_1fr]"><div className="rounded-xl bg-primary/5 p-4"><RetinaViewer mode="combined" /></div><div><div className="rounded-xl bg-emerald/10 p-4"><h3 className="font-display text-lg font-semibold">{hindi ? "मध्यम बदलाव पाए गए" : "Some changes were found"}</h3><p className="mt-2 text-sm leading-6 text-ink">{hindi ? "रेटिना में मधुमेह से जुड़े कुछ बदलाव दिखाई दिए हैं। आंखों के डॉक्टर से जांच कराना ज़रूरी है।" : "Some changes related to diabetes were found in the retina. An eye doctor should review this result."}</p><p className="mt-3 text-sm font-semibold text-emerald">{hindi ? "अगले 3 महीनों में आंखों की जांच कराएं।" : "Recommended: eye specialist check-up within 3 months."}</p></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><Metric label="ICDR Grade" value="Moderate" tone="warning" /><Metric label="Referral" value="Within 3 months" tone="good" /></div></div></div><div className="mt-5 flex flex-wrap items-center justify-between gap-3 border-t border-primary/10 pt-4"><div className="flex items-center gap-2"><select value={language} onChange={(event) => setLanguage(event.target.value)} className="rounded-lg border border-primary/10 bg-primary/5 px-3 py-2 text-xs"><option>English</option><option>हिन्दी</option><option>मराठी</option><option>தமிழ்</option><option>తెలుగు</option><option>বাংলা</option></select><button onClick={() => window.speechSynthesis?.speak(new SpeechSynthesisUtterance(hindi ? "मधुमेह से जुड़े कुछ बदलाव पाए गए हैं।" : "Some changes related to diabetes were found in the retina."))} className="inline-flex items-center gap-2 rounded-lg border border-primary/10 bg-primary/5 px-3 py-2 text-xs font-medium"><Activity className="size-3.5" /> Listen to Result</button></div><button onClick={onDownload} className="inline-flex items-center gap-2 rounded-lg bg-navy px-4 py-2.5 text-xs font-semibold text-primary-foreground"><Download className="size-3.5" /> Export Report</button></div><p className="mt-5 text-[11px] leading-4 text-mute">DrishtiAI is a screening and clinical decision-support prototype. It does not replace diagnosis by a qualified ophthalmologist.</p></div></div>; }

function Brand() { return <div className="flex items-center gap-2.5"><div className="grid size-9 place-items-center rounded-[11px] bg-emerald text-primary-foreground text-sm font-semibold shadow-sm">D</div><div className="leading-none"><div className="font-display text-[15px] font-semibold tracking-tight">DrishtiAI</div><div className="mt-1 text-[10px] uppercase tracking-[0.16em] text-mute">Explainable DR</div></div></div>; }
function PageHeader({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy: string; action?: React.ReactNode }) { return <div className="mb-5 flex flex-wrap items-end justify-between gap-4"><div><p className="text-[10px] font-semibold uppercase tracking-[0.18em] text-emerald">{eyebrow}</p><h1 className="mt-1 font-display text-2xl font-semibold tracking-tight sm:text-3xl">{title}</h1><p className="mt-1 max-w-2xl text-sm text-mute">{copy}</p></div>{action}</div>; }
function Panel({ title, subtitle, action, children }: { title: string; subtitle?: string; action?: React.ReactNode; children: React.ReactNode }) { return <section className="frosted spec-border rounded-2xl p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-display font-semibold">{title}</h2>{subtitle && <p className="mt-1 text-xs text-mute">{subtitle}</p>}</div>{action}</div>{children}</section>; }
function PrimaryButton({ children, onClick, className = "" }: { children: React.ReactNode; onClick?: () => void; className?: string }) { return <button onClick={onClick} className={`inline-flex items-center gap-2 rounded-lg bg-navy px-4 py-2.5 text-sm font-semibold text-primary-foreground transition hover:bg-navy/90 ${className}`}>{children}</button>; }
function Metric({ label, value, tone }: { label: string; value: string; tone?: "good" | "warning" }) { return <div className="rounded-xl bg-primary/5 p-3"><div className="text-[10px] uppercase tracking-[0.12em] text-mute">{label}</div><div className={`mt-1 font-display text-lg font-semibold ${tone === "good" ? "text-emerald" : tone === "warning" ? "text-coral" : ""}`}>{value}</div></div>; }
function StatusLine({ label, value, good }: { label: string; value: string; good?: boolean }) { return <div className="flex items-center justify-between gap-3"><span className="text-ink">{label}</span><span className={`flex items-center gap-1.5 font-medium ${good ? "text-emerald" : "text-navy"}`}>{good && <span className="size-1.5 rounded-full bg-emerald" />}{value}</span></div>; }
function Capability({ icon, title, copy }: { icon: React.ReactNode; title: string; copy: string }) { return <div className="frosted spec-border rounded-2xl p-4"><div className="grid size-10 place-items-center rounded-xl bg-emerald/15 text-emerald">{icon}</div><h3 className="mt-4 font-display font-semibold">{title}</h3><p className="mt-1.5 text-sm leading-5 text-ink">{copy}</p></div>; }
function Guidance({ icon, text }: { icon: React.ReactNode; text: string }) { return <div className="flex items-center gap-3"><span className="grid size-8 place-items-center rounded-lg bg-emerald/10 text-emerald">{icon}</span><span>{text}</span></div>; }
function Legend({ color, label }: { color: string; label: string }) { return <div className="flex items-center gap-2 text-mute"><span className={`size-2 rounded-full ${color}`} />{label}</div>; }
function ScenarioMenu({ value, onChange }: { value: Scenario; onChange: (value: Scenario) => void }) { return <div className="flex items-center gap-2"><span className="hidden text-xs text-mute sm:inline">Demo scenario</span><select value={value} onChange={(event) => onChange(event.target.value as Scenario)} className="rounded-lg border border-primary/10 bg-primary/5 px-3 py-2.5 text-xs font-medium outline-none"><option value="moderate">Moderate DR</option><option value="healthy">Healthy Retina</option><option value="poor">Poor Image</option><option value="clever">Clever Hans</option></select></div>; }